"""Release-pinned race conversion metadata, no game payload."""
import base64,zlib
READSET_B64=''
RECIPE_B64=''
PINS={'profile_id': 'wmmt-main2e-source16-fma2-avc1-135-race-restoration1', 'profile_sha256': 'dd5ba7761175b83652ff304f40fdc20fbb93d26d2aa5cb883e914ae9ff825f20', 'readset_sha256': '287be1d46467e26a793c04b1c7058edd218d65022aa5866779f57969da757e92', 'recipe_sha256': '87ee661e185f8ca04ad69674abb2efeb07dcaa7f2761fcbcc3b72bb63ff11e19'}
def load_bundle():
    result=dict(PINS)
    for key,packed in [('readset',READSET_B64),('recipe',RECIPE_B64)]:
        decoder=zlib.decompressobj();data=decoder.decompress(base64.b64decode(packed),8*1024*1024+1)
        if len(data)>8*1024*1024 or not decoder.eof or decoder.unused_data or decoder.unconsumed_tail:raise RuntimeError('Corrupt packaged metadata')
        result[key]=data
    return result
